planningClickActionMessage: "La visualizzazione Gantt offre ora due modalità operative distinte. <ul> <li>La modalità “visualizzazione dei dettagli con un solo clic”&#44 che è la modalità storica di ProjeQtOr.<br/> In questa modalità&#44 è sufficiente fare clic su una riga nella tabella per visualizzarne i dettagli .</li> <li>La &#34modalità di visualizzazione con doppio clic&#34&#44 è una nuova modalità introdotta nella versione V11.0.<br/> In questa modalità&#44 semplicemente facendo clic su una riga la si mette in modalità modifica.<br/> È necessario fare doppio clic sulla riga per visualizzare i dettagli.<br/> <b>Questa è la nuova modalità predefinita</b>.</li> </ul> Se vuoi tornare alla vecchia modalità operativa&#44 modifica l'impostazione nel pop-up dedicato tramite l'icona <img src='../view/img/iconThreePoints.png' style='width&#58 30px;top&#58 7px;position&# 58 relative;'/>.<br/> Puoi anche semplicemente fare clic con il tasto destro del mouse sulla riga per il menu contestuale.",
