startDayPeriod: "giorno di avvio del periodo",
startExecuteWaitingUpdates: "run awaiting consolidations",
startGuideActionCreate: "Creare",
startGuideActionMenu: "Seleziona il menu",
startGuideActivity: "Le attività sono i &#34;tasks&#34; pianificati nei tuoi progetti. <br/>Esse servono per creare le Work Breakdown Structure dei tuoi progetti. <br/>Non c'è limite al numero di livelli della struttura in phases / sub-phases / tasks / sub-tasks ...",
startGuideAffectation: "Una risorsa deve essere allocata ad un progetto per poter vedere le sue voci (items).<br/>l'Allocazione ad un progetto da automaticamente la visibilità delle voci (items) dei suoi sotto-progetti.",
startGuideClient: "I clienti sono i soggetti per i quali stai effettuando il lavoro.<br/>Essi possono essere interni o esterni alla tua organizzazione.",
startGuideContact: "I Contatti sono le persone con cui sei in contatto all'interno delle organizzazioni dei tuoi clienti.",
startGuideFooter: "In questa schermata sono riportate solo le funzioni principali <br/>Una volta che hai familiarizzato con queste funzioni sarai in grado di scoprire gli altri (numerosi) moduli presenti&#44; in grado di garantire la gestione completa dei tuoi progetti (projects management).",
startGuideImputation: "Le Risorse inseriscono il loro lavoro realmente effettuato giorno dopo giorno e attività per attività nella schermata &#34;Imputazione Lavoro Reale&#34; della voce di menu &#34;Gestione Lavoro&#34;.<br/> La ri-stima del lavoro « rimanente » permette l' attualizazione della pianificazione di progetto (project planning) con il progresso reale.",
startGuideIntro: "Questo è un breve aiuto per facilitare i tuoi primi passi con ProjeQtOr.<br>Segui questi passi per configurare i primi elementi.<br>Non esitare a premere [F1] per richiamare il manuale utente dove potrai trovare maggiore aiuto.<br>Ritorna alla pagina Oggi per trovare questa pagina di &#34;Start Guide&#34;.",
startGuideMilestone: "Le Milestones sono le date chiave dei progetti.<br/>Esse possono definire &#34;incoming&#34; (milestones fisse) o &#34;deliverables&#34; (milestones flessibili).",
startGuidePlanning: "La Pianificazione propone una vista Gantt. Per pianificare le varie attività occorre prima assegnare loro le risorse <br/>e definire il lavoro che deve essere svolto perchè la Pianificazione è guidata dal lavoro (work driven).<br/>Quindi puoi definire le relazioni tra le attività (legami di precedenza) e le milestones...<br/>Infine puoi lanciare il calcolo della pianificazione considerando tutti i vincoli sulle risorse come la loro disponibilità.",
startGuideProject: "Il Progetto è l'oggetto principale in ProjeQtOr.<br/>In ProjeQtOr&#44; ogni cosa (item) è collegata ad un progetto.<br/>Anche i diritti di accesso sono definiti a livello di progetto.",
startGuideResource: "Le Risorse sono le persone che lavoreranno sulle attività.<br/>Se selezioni  « è un utente » la risorsa potrà connettersi a ProjeQtOr.",
startGuideTicket: "I Tickets ti permettono di seguire ogni evento puntuale collegato al progetto come i bugs o qualsiasi tipo di richiesta<br/>Essi possono essere facilmente copiati in attività quando necessario o opportuno&#44; senza dover reintrodurre alcun dato e mantenendo il collegamento con la richiesta originale.",
startGuideTitle: "Start Guide",
startGuideUser: "Gli Utenti sono le persone che possono connettersi all'applicazione. <br/>Essi devono avere un profilo che determinerà i diritti di accesso ai vari elementi.",
